class _Rules(Rules):
    DOSE = __DOSE__

    TARGET_SIG = ('diningtable 1', 'lettuce', 'sinkbasin 1', 'countertop 1')

    def _is_target(self, cmd):
        return any(s in cmd for s in self.TARGET_SIG)

    def _is_distractor(self, cmd):
        return ('cabinet' in cmd) or ('fridge' in cmd) or ('garbagecan' in cmd)

    def filter_observation(self, obs, env_state):
        cmds = list(obs.data.get('admissible_commands') or [])
        if not cmds:
            return obs
        target = [c for c in cmds if self._is_target(c)]
        other = [c for c in cmds if not self._is_target(c) and not self._is_distractor(c)]
        distractor = [c for c in cmds if self._is_distractor(c)]
        if self.DOSE <= 0:
            return obs
        if self.DOSE < 0.5:
            new_cmds = target + other + distractor
        else:
            new_cmds = target + other
        if not new_cmds:
            return obs
        new_data = dict(obs.data)
        new_data['admissible_commands'] = new_cmds
        return Observation(text=obs.text, data=new_data)

