class _Rules(Rules):
    DOSE = __DOSE__

    def filter_observation(self, obs, env_state):
        if self.DOSE <= 0:
            return obs
        cmds = list(obs.data.get('admissible_commands') or [])
        distractors = ['cabinet', 'drawer', 'microwave', 'toaster', 'fridge']
        keep_goal = [c for c in cmds if 'glassbottle' in c]
        keep_nav = [c for c in cmds if c.startswith('go to ') and not any(d in c for d in distractors)]
        keep_other = [c for c in cmds if not c.startswith('go to ') and not any(d in c for d in distractors)]
        # DOSE controls how aggressively we drop distractor container commands.
        if self.DOSE >= 0.8:
            cmds = keep_goal + keep_nav + keep_other
        elif self.DOSE >= 0.4:
            cmds = keep_goal + keep_nav + [c for c in cmds if c not in keep_goal and c not in keep_nav]
        new_data = dict(obs.data)
        new_data['admissible_commands'] = cmds
        return Observation(text=obs.text, data=new_data)

