class _Rules(Rules):
    DOSE = __DOSE__

    def _hint(self, d):
        if d <= 0:
            return None
        return "Hint: the ladle is on a countertop."

    def filter_observation(self, obs, env_state):
        d = self.DOSE
        if d <= 0:
            return obs
        text = obs.text
        data = dict(obs.data) if obs.data is not None else {}
        cmds = list(data.get("admissible_commands") or [])

        # Reorder admissible commands: put 'go to countertop' commands first.
        countertop_cmds = [c for c in cmds if c.startswith("go to countertop")]
        other_cmds = [c for c in cmds if not c.startswith("go to countertop")]
        cmds = countertop_cmds + other_cmds
        data["admissible_commands"] = cmds

        # At higher DOSE, prune distracting cabinet/drawer go-to commands to
        # reduce the search space (never remove interaction commands).
        if d >= 0.5:
            keep = [c for c in cmds if not (c.startswith("go to cabinet") or c.startswith("go to drawer"))]
            if keep:
                cmds = keep
                data["admissible_commands"] = cmds

        # Add an increasingly salient hint to the text.
        hint = self._hint(d)
        if hint:
            if "Admissible commands:" in text:
                text = text.replace("Admissible commands:", hint + "\n\nAdmissible commands:", 1)
            else:
                text = text + "\n\n" + hint

        return Observation(text=text, data=data)

class _Rules(Rules):
    DOSE = __DOSE__

    def filter_action(self, action, env_state):
        d = self.DOSE
        if d <= 0:
            return action
        text = (action.kwargs or {}).get("text", "") if action is not None else ""
        if not text:
            return action

        # Always allow goal-critical actions.
        if ("take ladle" in text or "clean ladle" in text or "move ladle" in text
                or "put ladle" in text or "examine ladle" in text or text.strip() == "look"):
            return action

        # Block opening/closing cabinets and drawers (searching empty containers).
        if ("open cabinet" in text or "close cabinet" in text
                or "open drawer" in text or "close drawer" in text):
            return Blocked(reason="Try looking on the countertops instead.")

        # At higher DOSE, also block wandering to cabinets/drawers.
        if d >= 0.5 and ("go to cabinet" in text or "go to drawer" in text):
            return Blocked(reason="The ladle is on a countertop; go to a countertop.")

        return action
